export class WaferFabError extends Error{constructor(code,message,details={}){super(message);this.name='WaferFabError';this.code=code;this.details=details;}}
const fail=(c,m,d={})=>{throw new WaferFabError(c,m,d)};const finite=v=>typeof v==='number'&&Number.isFinite(v);const key=(x,y)=>`${x},${y}`;
export function normalizeWafer(input={}){if(!Array.isArray(input.dies))fail('WAFER_DIES','dies must be array');const diameter=+input.diameterMm;if(!finite(diameter)||diameter<=0)fail('WAFER_DIAMETER','diameterMm must be positive');const seen=new Set();const dies=input.dies.map((d,i)=>{const x=+d.x,y=+d.y;if(!Number.isInteger(x)||!Number.isInteger(y))fail('WAFER_COORD','die coordinates must be integers',{i});const k=key(x,y);if(seen.has(k))fail('WAFER_DUPLICATE','duplicate die coordinate',{k});seen.add(k);const value=d.value===null||d.value===undefined?null:+d.value;if(value!==null&&!finite(value))fail('WAFER_VALUE','die value must be finite or missing');return Object.freeze({x,y,value,missing:value===null});});return Object.freeze({id:String(input.id??'wafer'),diameterMm:diameter,diePitchX:+input.diePitchX||1,diePitchY:+input.diePitchY||1,orientationDeg:((+input.orientationDeg||0)%360+360)%360,unit:String(input.unit??''),provenance:String(input.provenance??'measured'),dies:Object.freeze(dies)});}
function rotate(x,y,deg){const d=((deg%360)+360)%360;if(d===0)return[x,y];if(d===90)return[-y,x];if(d===180)return[-x,-y];if(d===270)return[y,-x];const r=d*Math.PI/180,c=Math.cos(r),s=Math.sin(r);return[Math.round(x*c-y*s),Math.round(x*s+y*c)];}
export function registerWafer(waferInput,options={}){const w=normalizeWafer(waferInput),rot=+options.rotateDeg||0,dx=+options.dx||0,dy=+options.dy||0;if(!finite(dx)||!finite(dy))fail('WAFER_REGISTER','registration offsets must be finite');return Object.freeze({...w,dies:Object.freeze(w.dies.map(d=>{const [x,y]=rotate(d.x,d.y,rot);return Object.freeze({...d,x:x+dx,y:y+dy});})),registration:Object.freeze({rotateDeg:rot,dx,dy})});}
export function compareWafers(aInput,bInput,options={}){const a=normalizeWafer(aInput),b=registerWafer(bInput,options.registration??{});if(Math.abs(a.diameterMm-b.diameterMm)>1e-9)fail('WAFER_GEOMETRY','wafer diameters mismatch');if(a.unit!==b.unit)fail('WAFER_UNIT','wafer units mismatch');const bm=new Map(b.dies.map(d=>[key(d.x,d.y),d]));const cells=a.dies.map(d=>{const other=bm.get(key(d.x,d.y));const missingA=d.value===null,missingB=!other||other.value===null;return Object.freeze({x:d.x,y:d.y,a:d.value,b:other?.value??null,delta:missingA||missingB?null:other.value-d.value,missingA,missingB});});return Object.freeze({a,b,cells:Object.freeze(cells),registered:true});}
export function prepareFabMatrix(input={}){const rows=(input.rows??[]).map(String),columns=(input.columns??[]).map(String);if(!rows.length||!columns.length)fail('FAB_MATRIX','matrix requires row/column labels');const cells=[];for(let r=0;r<rows.length;r++)for(let c=0;c<columns.length;c++){const v=input.values?.[r]?.[c];const value=v===null||v===undefined?null:+v;if(value!==null&&!finite(value))fail('FAB_VALUE','matrix values must be finite or missing');cells.push(Object.freeze({row:rows[r],column:columns[c],value,missing:value===null,zero:value===0}));}return Object.freeze({rows:Object.freeze(rows),columns:Object.freeze(columns),cells:Object.freeze(cells),unit:String(input.unit??''),provenance:String(input.provenance??'measured')});}
